@layer base {
  input:where([type="button"], [type="submit"], [type="reset"]), button {
    --btn-border-radius: var(--default-border-radius);
    --btn-font-size: 0.875rem;
    --btn-color: var(--color-title);
    --btn-leading: var(--leading-normal);
    --btn-height: calc(var(--spacing) * 8);
    --btn-padding-x: calc(var(--btn-height)/3);
    --btn-border-width: 1px;
    --btn-border-color: var(--color-title-bd);
    --btn-background: var(--color-title-surface);
    --btn-outline-color: var(--color-primary);
    --btn-gap: 0.4em;
    border-radius: var(--btn-border-radius);
    font-size: var(--btn-font-size);
    color: var(--btn-color);
    line-height: var(--btn-leading);
    border: var(--btn-border-width) solid var(--btn-border-color);
    height: var(--btn-height);
    padding-inline: var(--btn-padding-x);
    background-color: var(--btn-background);
    opacity: inherit;
    cursor: pointer;
    gap: var(--btn-gap);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    --: ;
    transition: var(--transition-all-normal);
    &:where([disabled]) {
      cursor: not-allowed;
      opacity: var(--default-opacity-disabled, 0.5);
    }
    &:where(:not([disabled]):hover) {
      --btn-border-color: var(--color-primary);
      --btn-color: var(--color-primary);
    }
    &:where(:not([disabled]):active) {
      --btn-color: var(--color-primary-hover);
    }
    &:where(:not([disabled]):focus-visible) {
      --btn-border-color: var(--color-primary);
      outline-color: var(--btn-outline-color);
    }
  }
}
